215:     .check_multi_interp_extensions = 1,
216:     .gil = PyInterpreterConfig_OWN_GIL,
217: };
218: PyThreadState *tstate = NULL;
219: PyStatus status = Py_NewInterpreterFromConfig(&tstate, &config);
220: if (PyStatus_Exception(status)) {
221:     return -1;
