  "arguments": "{\"action\":\"read\",\"query\":\"distutils removed setuptools pre-install virtual environments gh-95299 pip install setuptools\",\"snapshotId\":\"capture-a778cda3-f4ce-4bd0-b333-b48cf564d613\"}",
